{
  "themes": [
    {
      "cluster": 12,
      "name": "iCloud Photo Deletion Sync Issues",
      "description": "Customers report that deleted photos remain in iCloud or disappear unexpectedly, and they seek help removing or syncing photos across devices."
    },
    {
      "cluster": 13,
      "name": "Apple ID Phishing and Scam Emails",
      "description": "Users receive suspicious emails or calls claiming to be from Apple and want verification and guidance on handling potential scams."
    },
    {
      "cluster": 14,
      "name": "Podcast App Auto‑Play and Sync Failures",
      "description": "Listeners experience broken auto‑play, missing queue, and unsynced episode status after iOS or Podcasts app updates."
    },
    {
      "cluster": 15,
      "name": "iPhone Pre‑Order and Order Confirmation Problems",
      "description": "Buyers cannot locate order confirmations, cancel pre‑orders, or encounter account‑mismatch errors for iPhone purchases."
    },
    {
      "cluster": 16,
      "name": "Apple Support Scheduling and Service Quality Complaints",
      "description": "Customers struggle to schedule calls, experience missed callbacks, and report poor in‑store or phone support experiences."
    },
    {
      "cluster": 17,
      "name": "Missing or Corrupt Emoji Display",
      "description": "Users see question‑mark boxes or no emojis after updates and request a fix for the broken emoji rendering."
    },
    {
      "cluster": 18,
      "name": "Boxed Question‑Mark Glyph Glitch After Update",
      "description": "After updating the device, users continue to see small boxes with question marks in text and demand a resolution."
    },
    {
      "cluster": 19,
      "name": "Battery Health Check Requests",
      "description": "Customers ask how to view or test the battery health of iPhones and iPads without visiting a store."
    },
    {
      "cluster": 20,
      "name": "Apple Pay Setup and Regional Availability Issues",
      "description": "Users encounter non‑functioning Apple Pay, need guidance on adding cards, or inquire about availability in specific countries."
    },
    {
      "cluster": 21,
      "name": "Persistent Question‑Mark Boxes in Text",
      "description": "People report ongoing appearance of boxed question marks in messages and request an immediate fix."
    },
    {
      "cluster": 22,
      "name": "Post‑Update Question‑Mark Glyph Bug",
      "description": "After a phone update, users continue to see characters rendered as question‑mark boxes and seek a software correction."
    },
    {
      "cluster": 23,
      "name": "Payment Method Errors and Unwanted Charges",
      "description": "Customers experience problems updating credit cards, unwanted charges, accidental in‑app purchases, and restrictions on free app downloads."
    }
  ]
}
